func (c *Controller) Cancel(signal signalFloat32) {
	delete(c.active, any(signal))
}

func (c *Controller) CancelAll() {
	for key := range c.active {
		delete(c.active, key)
	}
	c.compositions = c.compositions[:0]
}

func (c *Controller) HasActive() bool {
	return len(c.active) > 0 || len(c.compositions) > 0
}

func NewController() *Controller {
	return &Controller{
		active: make(map[any]animatable),
	}
}

func (c *Controller) Tick(dt time.Duration) bool {
	// Tick signal-keyed animations.
	for key, anim := range c.active {
		if anim.step(dt) {
			delete(c.active, key)
		}
	}

	// Tick compositions.
	n := 0
	for _, comp := range c.compositions {
		if !comp.step(dt) {
			c.compositions[n] = comp
			n++
		}
	}
	// Clear references to allow GC.
	for i := n; i < len(c.compositions); i++ {
		c.compositions[i] = nil
	}
	c.compositions = c.compositions[:n]

	return len(c.active) > 0 || len(c.compositions) > 0
}

type Controller struct {
	// active animations indexed by signal identity for O(1) auto-cancel lookup.
	active	map[any]animatable

	// compositions (Sequence/Parallel) that don't target a single signal.
	compositions	[]animatable
}

func Chain(animations ...Startable) *SequenceBuilder {
	return NewSequence(animations...)
}

func Group(animations ...Startable) *ParallelBuilder {
	return NewParallel(animations...)
}

func (b *RepeatingBuilder) OnDone(fn func()) *RepeatingBuilder {
	b.rep.onDone = fn
	return b
}

func RepeatForever(anim Startable) *RepeatingBuilder {
	return RepeatN(0, anim)
}

func RepeatN(n int, anim Startable) *RepeatingBuilder {
	return &RepeatingBuilder{
		rep: &repeating{
			factory:	anim,
			maxCount:	n,
		},
	}
}

func Reverse(anim Startable) Startable {
	return &reversedStartable{inner: anim}
}

func Stagger(delay time.Duration, animations ...Startable) *ParallelBuilder {
	staggered := make([]Startable, len(animations))
	for i, anim := range animations {
		if i == 0 {
			staggered[i] = anim
			continue
		}
		staggered[i] = &delayedStartable{
			inner:	anim,
			delay:	time.Duration(i) * delay,
		}
	}
	return NewParallel(staggered...)
}

func (b *RepeatingBuilder) Start(ctrl *Controller) {
	ctrl.addComposition(b.rep)
}

func WithDelay(delay time.Duration, anim Startable) Startable {
	return &delayedStartable{
		inner:	anim,
		delay:	delay,
	}
}

type RepeatingBuilder struct {
	rep *repeating
}

func DialogEnter(opacity, scale signalFloat32) *ParallelBuilder {
	return NewParallel(
		FadeIn(opacity, DurationMedium2),
		ScaleIn(scale, DurationMedium2),
	)
}

func DialogExit(opacity, scale signalFloat32) *ParallelBuilder {
	return NewParallel(
		FadeOut(opacity, DurationShort4),
		ScaleOut(scale, DurationShort4),
	)
}

func FadeIn(signal signalFloat32, duration time.Duration) *AnimationBuilder {
	return To(signal, 1.0).
		From(0.0).
		Duration(duration).
		Ease(M3StandardDecelerate)
}

func FadeOut(signal signalFloat32, duration time.Duration) *AnimationBuilder {
	return To(signal, 0.0).
		From(1.0).
		Duration(duration).
		Ease(M3StandardAccelerate)
}

func MenuEnter(opacity, translateY signalFloat32, distance float32) *ParallelBuilder {
	return NewParallel(
		FadeIn(opacity, DurationShort4),
		SlideInFromTop(translateY, distance, DurationShort4),
	)
}

func MenuExit(opacity, translateY signalFloat32, distance float32) *ParallelBuilder {
	return NewParallel(
		FadeOut(opacity, DurationShort3),
		To(translateY, -distance).
			From(0).
			Duration(DurationShort3).
			Ease(M3StandardAccelerate),
	)
}

func ScaleIn(signal signalFloat32, duration time.Duration) *AnimationBuilder {
	return To(signal, 1.0).
		From(0.8).
		Duration(duration).
		Ease(M3EmphasizedDecelerate)
}

func ScaleOut(signal signalFloat32, duration time.Duration) *AnimationBuilder {
	return To(signal, 0.8).
		From(1.0).
		Duration(duration).
		Ease(M3EmphasizedAccelerate)
}

func SlideInFromBottom(signal signalFloat32, distance float32, duration time.Duration) *AnimationBuilder {
	return To(signal, 0.0).
		From(distance).
		Duration(duration).
		Ease(M3EmphasizedDecelerate)
}

func SlideInFromLeft(signal signalFloat32, distance float32, duration time.Duration) *AnimationBuilder {
