func (b *SpringBuilder) Build() *Spring {
	s := b.spring
	// Convert damping ratio to damping coefficient: d = 2 * zeta * sqrt(k * m)
	if b.dampingSet {
		s.damping = 2 * b.dampingRatio * float32(math.Sqrt(float64(s.stiffness*s.mass)))
	}
	return s
}

