func (tc *threePointCubic) Evaluate(x float32) float32 {
	if x <= 0 {
		return 0
	}
	if x >= 1 {
		return 1
	}

	midX := tc.midpoint[0]
	midY := tc.midpoint[1]

	if x < midX {
		// First segment: normalize x to [0,1] within segment range.
		if midX <= 0 {
			return 0
		}
		localT := x / midX
		return tc.seg1.Evaluate(localT) * midY
	}

	// Second segment: normalize x to [0,1] within segment range.
	rangeX := 1 - midX
	rangeY := 1 - midY
	if rangeX <= 0 {
		return 1
	}
	localT := (x - midX) / rangeX
	return midY + tc.seg2.Evaluate(localT)*rangeY
}

func ThreePointCubic(a1, b1, mid, a2, b2 [2]float32) Easing {
	tc := newThreePointCubic(a1, b1, mid, a2, b2)
	return tc.Evaluate
}

func (tw *Tween[T]) At(t float32) T {
	return tw.lerp(tw.begin, tw.end, t)
}

func LerpColor(begin, end widget.Color, t float32) widget.Color {
	return begin.Lerp(end, t)
}

func LerpFloat32(begin, end, t float32) float32 {
	return begin + (end-begin)*t
}

func LerpPoint(begin, end geometry.Point, t float32) geometry.Point {
	return begin.Lerp(end, t)
}

func LerpSize(begin, end geometry.Size, t float32) geometry.Size {
	return geometry.Size{
		Width:	begin.Width + (end.Width-begin.Width)*t,
		Height:	begin.Height + (end.Height-begin.Height)*t,
	}
}

func NewColorTween(begin, end widget.Color) *Tween[widget.Color] {
	return NewTween(begin, end, LerpColor)
}

func NewFloat32Tween(begin, end float32) *Tween[float32] {
