}

func NewSizeTween(begin, end geometry.Size) *Tween[geometry.Size] {
	return NewTween(begin, end, LerpSize)
}

func NewTween[T any](begin, end T, lerpFn LerpFunc[T]) *Tween[T] {
	return &Tween[T]{begin: begin, end: end, lerp: lerpFn}
}

