func (c *containerBase) Remove(child Layer) {
	for i, ch := range c.children {
		if ch == child {
			child.SetParent(nil)
			c.children = append(c.children[:i], c.children[i+1:]...)
			c.MarkNeedsCompositing()
			return
		}
	}
}

