func (w *Widget) VisibleRowRange() (start, end int) {
	rowCount := w.cfg.ResolvedRowCount()
	if rowCount == 0 {
		return 0, 0
	}
	scrollY := w.currentScrollY()
	dataViewH := w.viewportHeight - defaultHeaderHeight
	if dataViewH <= 0 {
		return 0, 0
	}
	first, last := w.visibleRowRange(scrollY, dataViewH)
	if last >= rowCount {
		last = rowCount - 1
	}
	if first > last {
		first = last
	}
	return first, last + 1
}

