	}

	// Handle keyboard events at the grid level.
	if ke, ok := e.(*event.KeyEvent); ok {
		if w.handleKeyEvent(ctx, ke) {
			return true
		}
	}

	// Delegate other events to the scroll view.
	return w.scroll.Event(ctx, e)
