	canvas.DrawRoundRect(st.Bounds, tipBgColor, tipRadius)

	// Text.
	textBounds := geometry.Rect{
		Min:	geometry.Pt(st.Bounds.Min.X+tooltipPadH, st.Bounds.Min.Y),
		Max:	geometry.Pt(st.Bounds.Max.X-tooltipPadH, st.Bounds.Max.Y),
