func (w *Widget) Children() []widget.Widget {
	var children []widget.Widget
	for _, item := range w.cfg.items {	//nolint:gocritic
		if item.Kind == ItemCustom && item.Widget != nil {
			children = append(children, item.Widget)
		}
	}
	return children
