	if selectedID != "" && root != nil {
		if node := findNodeByID(root, selectedID); node != nil {
			return fmt.Sprintf("Selected: %s, %d visible rows", node.Label, len(w.rows))
		}
	}
	return fmt.Sprintf("%d visible rows", len(w.rows))
