func (s Shortcut) Matches(e *event.KeyEvent) bool {
	if e.Key != s.Key {
		return false
	}

	mods := e.Modifiers()

	if s.Ctrl != mods.IsCtrl() {
		return false
	}
	if s.Shift != mods.IsShift() {
		return false
	}
	if s.Alt != mods.IsAlt() {
		return false
	}

	return true
}

