func (c Constraints) Normalize() Constraints {
	minW := max32(0, c.MinWidth)
	maxW := max32(0, c.MaxWidth)
	minH := max32(0, c.MinHeight)
	maxH := max32(0, c.MaxHeight)

	// Ensure min <= max
	if minW > maxW {
		minW = maxW
	}
	if minH > maxH {
		minH = maxH
	}

	return Constraints{
		MinWidth:	minW,
		MaxWidth:	maxW,
		MinHeight:	minH,
		MaxHeight:	maxH,
	}
}

func (c Constraints) Sanitize() Constraints {
