	}
	if isNaN32(maxW) {
		maxW = Infinity
	}
	if isNaN32(minH) {
		minH = 0
	}
	if isNaN32(maxH) {
		maxH = Infinity
	}
	return Constraints{
		MinWidth:	minW,
