func (r Rect) Intersection(other Rect) Rect {
	result := Rect{
		Min:	r.Min.Max(other.Min),
		Max:	r.Max.Min(other.Max),
	}
	// Return empty rect if no intersection
	if result.Min.X >= result.Max.X || result.Min.Y >= result.Max.Y {
		return Rect{}
	}
	return result
}

