func PluralRuleEnglish(count int) PluralCategory {
	if abs(count) == 1 {
		return PluralOne
	}
	return PluralOther
}

func PluralRuleFrench(count int) PluralCategory {
	n := abs(count)
	if n <= 1 {
		return PluralOne
	}
	return PluralOther
}

func PluralRuleJapanese(count int) PluralCategory {
	_ = count	// all counts map to other
	return PluralOther
}

func PluralRulePolish(count int) PluralCategory {
	n := abs(count)
	mod10 := n % 10
	mod100 := n % 100

	switch {
	case n == 1:
		return PluralOne
	case mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14):
		return PluralFew
	default:
		return PluralMany
	}
}

func PluralRuleRussian(count int) PluralCategory {
	n := abs(count)
	mod10 := n % 10
	mod100 := n % 100

	switch {
	case mod10 == 1 && mod100 != 11:
		return PluralOne
	case mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14):
		return PluralFew
	default:
		return PluralMany
	}
}

