	canvas.DrawRoundRect(shadowBounds, shadow, m3PopoverRadius)

	// Background.
	canvas.DrawRoundRect(st.Bounds, bg, m3PopoverRadius)

	// Border.
	canvas.StrokeRoundRect(st.Bounds, border, m3PopoverRadius, m3PopoverBorderWidth)
}

