		BottomLeft:	radius,
	}
}

func (c CornerRadius) Max() float32 {
	maxVal := c.TopLeft
	if c.TopRight > maxVal {
		maxVal = c.TopRight
	}
	if c.BottomRight > maxVal {
		maxVal = c.BottomRight
	}
	if c.BottomLeft > maxVal {
		maxVal = c.BottomLeft
	}
	return maxVal
}

func Right(radius float32) CornerRadius {
	return CornerRadius{
		TopLeft:	0,
		TopRight:	radius,
		BottomRight:	radius,
		BottomLeft:	0,
