func (r *ThemeRegistry) Unregister(name string) bool {
	r.mu.Lock()
	defer r.mu.Unlock()

	if _, ok := r.themes[name]; ok {
		delete(r.themes, name)
		delete(r.info, name)
		return true
	}
	return false
}

