	return Effect{
		OpacityStart:	0,
		OpacityEnd:	1,
		ScaleStart:	noScale,
	}
}

func FadeOut() Effect {
	return Effect{
		OpacityStart:	1,
		OpacityEnd:	0,
		ScaleStart:	noScale,
	}
}

func (e Effect) IsNone() bool {
	hasOpacity := e.OpacityStart >= 0
	hasTranslate := e.TranslateXFraction != 0 || e.TranslateYFraction != 0
	hasScale := e.ScaleStart >= 0
	return !hasOpacity && !hasTranslate && !hasScale
}

func None() Effect {
	return Effect{
		OpacityStart:	noOpacity,
		ScaleStart:	noScale,
	}
}

func ScaleIn() Effect {
	return Effect{
		OpacityStart:	0,
		OpacityEnd:	1,
		ScaleStart:	0.8,
		ScaleEnd:	1.0,
	}
}

func ScaleOut() Effect {
	return Effect{
		OpacityStart:	1,
		OpacityEnd:	0,
		ScaleStart:	1.0,
		ScaleEnd:	0.8,
	}
}

func SlideIn(dir Direction) Effect {
	e := Effect{
		OpacityStart:	noOpacity,
		ScaleStart:	noScale,
	}
	switch dir {
	case FromTop, ToTop:
		e.TranslateYFraction = -1.0
	case FromBottom, ToBottom:
		e.TranslateYFraction = 1.0
	case FromLeft, ToLeft:
		e.TranslateXFraction = -1.0
	case FromRight, ToRight:
		e.TranslateXFraction = 1.0
	}
	return e
}

func SlideOut(dir Direction) Effect {
	e := Effect{
		OpacityStart:	noOpacity,
		ScaleStart:	noScale,
	}
	switch dir {
	case ToTop, FromTop:
		e.TranslateYFraction = -1.0
	case ToBottom, FromBottom:
		e.TranslateYFraction = 1.0
	case ToLeft, FromLeft:
		e.TranslateXFraction = -1.0
	case ToRight, FromRight:
		e.TranslateXFraction = 1.0
	}
	return e
}

type Effect struct {
	// OpacityStart is the starting opacity. Negative means opacity is not animated.
	OpacityStart	float64
	// OpacityEnd is the ending opacity.
	OpacityEnd	float64

	// TranslateXFraction is the starting X offset as a fraction of widget width.
	// For example, -1.0 means start one full width to the left.
	TranslateXFraction	float64
	// TranslateYFraction is the starting Y offset as a fraction of widget height.
	TranslateYFraction	float64

	// ScaleStart is the starting scale factor. Negative means scale is not animated.
	ScaleStart	float64
	// ScaleEnd is the ending scale factor.
	ScaleEnd	float64
}

func (f *Fade) Child() widget.Widget {
	return f.child
}

func (f *Fade) Children() []widget.Widget {
	if f.child == nil {
		return nil
	}
	return []widget.Widget{f.child}
}

func (f *Fade) Draw(ctx widget.Context, canvas widget.Canvas) {
	if f.child == nil {
		return
	}

	// Update animation progress.
	if f.animating {
		f.updateAnimation(ctx)
	}

	// At zero opacity, skip drawing entirely.
	if f.opacity <= 0 {
		return
	}

	// At full opacity, draw child directly (no overhead).
	if f.opacity >= 1.0 {
		f.child.Draw(ctx, canvas)
		return
	}

	// Try OpacityPusher for true per-pixel opacity.
	if op, ok := canvas.(OpacityPusher); ok {
		op.PushOpacity(float64(f.opacity))
		f.child.Draw(ctx, canvas)
		op.PopOpacity()
		return
	}

	// Fallback: draw child, then overlay with background color at (1-opacity) alpha.
	f.child.Draw(ctx, canvas)
	overlayAlpha := 1.0 - f.opacity
	overlay := widget.RGBA(f.bgColor.R, f.bgColor.G, f.bgColor.B, overlayAlpha)
	bounds := childBoundsOf(f.child, f.Bounds().Size(), f.Bounds().Min)
	canvas.DrawRect(bounds, overlay)
}

