func (c *MockCanvas) PopTransform() {
	c.PopTransformCount++
	if len(c.transformStack) > 0 {
		lastIdx := len(c.transformStack) - 1
		c.currentOffset = c.transformStack[lastIdx]
		c.transformStack = c.transformStack[:lastIdx]
	}
}

