func (c Color) Lerp(other Color, t float32) Color {
	return Color{
		R:	c.R + (other.R-c.R)*t,
		G:	c.G + (other.G-c.G)*t,
		B:	c.B + (other.B-c.B)*t,
		A:	c.A + (other.A-c.A)*t,
	}
}

