func (c *ContextImpl) BeginFrame(now time.Time) {
	c.mu.Lock()
	defer c.mu.Unlock()
	dt := now.Sub(c.lastFrame)
	if dt < 0 {
		dt = 0
	}
	if dt > maxDeltaTime {
		dt = maxDeltaTime
	}
	c.deltaTime = dt
	c.lastFrame = now
	c.now = now
}

