type Focusable interface {
	// IsFocusable reports whether this widget can currently receive focus.
	//
	// A widget may return false if it is disabled, invisible, or otherwise
	// unable to accept keyboard input at this time.
	IsFocusable() bool

	// SetFocused sets the widget's focus state.
	//
	// The focus manager calls this when focus is granted or revoked.
	// Widgets should update their visual appearance accordingly.
	SetFocused(focused bool)

	// IsFocused reports whether this widget currently has keyboard focus.
	IsFocused() bool
}

func MountTree(w Widget, ctx Context) {
	if w == nil {
		return
	}

	// Set mounted state on WidgetBase if available.
	if m, ok := w.(interface{ IsMounted() bool }); ok && m.IsMounted() {
		return	// already mounted
	}
	if base, ok := w.(interface{ SetMounted(bool) }); ok {
		base.SetMounted(true)
	}

	// Call Mount if widget implements Lifecycle.
	if lc, ok := w.(Lifecycle); ok {
		lc.Mount(ctx)
	}

	// Recurse into children, establishing parent chain.
	// Flutter adoptChild pattern: every child knows its parent so that
	// propagateDirtyUpward can walk to the nearest RepaintBoundary.
	if children := w.Children(); children != nil {
		for _, child := range children {
			if setter, ok := child.(interface{ SetParent(Widget) }); ok {
				setter.SetParent(w)
			}
			MountTree(child, ctx)
		}
	}
}

func UnmountTree(w Widget) {
	if w == nil {
		return
	}

	// Recurse into children first (bottom-up unmount).
	if children := w.Children(); children != nil {
		for _, child := range children {
			UnmountTree(child)
		}
	}

	// Cleanup bindings on WidgetBase.
	if base, ok := w.(interface{ CleanupBindings() }); ok {
		base.CleanupBindings()
	}

	// Call Unmount if widget implements Lifecycle.
	if lc, ok := w.(Lifecycle); ok {
		lc.Unmount()
	}

	// Clear parent link.
	if setter, ok := w.(interface{ SetParent(Widget) }); ok {
		setter.SetParent(nil)
	}

	// Clear cached scene to release scene memory (prevents leak after SetRoot).
	type sceneClearer interface{ ClearCachedScene() }
	if sc, ok := w.(sceneClearer); ok {
		sc.ClearCachedScene()
	}

	// Clear mounted state.
	if base, ok := w.(interface{ SetMounted(bool) }); ok {
		base.SetMounted(false)
	}
}

type Lifecycle interface {
	// Mount is called when the widget is added to the tree.
	// Implementations should create signal bindings here via AddBinding().
	Mount(ctx Context)

	// Unmount is called when the widget is removed from the tree.
	// Implementations should clean up any resources not managed by AddBinding().
	// WidgetBase.CleanupBindings() is called automatically before Unmount().
	Unmount()
}

func ClearRedrawInTree(w Widget) {
	if w == nil {
		return
	}

	// Clear this widget's flag.
	type redrawClearer interface {
		ClearRedraw()
	}
	if rc, ok := w.(redrawClearer); ok {
		rc.ClearRedraw()
	}

	// Recurse into children.
	for _, child := range w.Children() {
		ClearRedrawInTree(child)
	}
}

func MarkRedrawInTree(w Widget) {
	if w == nil {
		return
	}

	// Mark this widget.
	type redrawSetter interface {
		SetNeedsRedraw(bool)
	}
	if rs, ok := w.(redrawSetter); ok {
		rs.SetNeedsRedraw(true)
	}

	// If widget is a PARENTLESS RepaintBoundary (root), invalidate its scene.
	// Root has no parent → propagateDirtyUpward from SetNeedsRedraw is no-op →
	// scene stays clean → stale scene replayed. Only invalidate parentless
	// boundaries, not child boundaries — over-invalidation causes full
	// repaint every frame (entire cyan overlay).
	type boundaryInvalidator interface {
		IsRepaintBoundary() bool
		InvalidateScene()
	}
	if bi, ok := w.(boundaryInvalidator); ok && bi.IsRepaintBoundary() {
		isRoot := true
		if pc, ok2 := w.(interface{ Parent() Widget }); ok2 && pc.Parent() != nil {
			isRoot = false
		}
		if isRoot {
			bi.InvalidateScene()
		}
	}

	// Recurse into children.
	for _, child := range w.Children() {
		MarkRedrawInTree(child)
	}
}

func NeedsRedrawInTree(w Widget) bool {
	if w == nil {
		return false
	}

	// Check this widget's redraw flag.
	type redrawChecker interface {
		NeedsRedraw() bool
	}
	if rc, ok := w.(redrawChecker); ok {
		if rc.NeedsRedraw() {
			return true
		}
	} else {
		// Widget doesn't implement NeedsRedraw — assume it needs redraw
		// for safety (custom widgets without WidgetBase).
		return true
	}

	// Recurse into children.
	for _, child := range w.Children() {
		if NeedsRedrawInTree(child) {
			return true
		}
	}

	return false
}

func NeedsRedrawInTreeNonBoundary(w Widget) bool {
	if w == nil {
		return false
	}

	type boundaryChecker interface {
		IsRepaintBoundary() bool
	}
	isBoundary := false
	if bc, ok := w.(boundaryChecker); ok && bc.IsRepaintBoundary() {
		isBoundary = true
	}

	// Only count non-boundary widgets as dirty triggers.
	// Boundaries manage their own dirty state independently.
	if !isBoundary {
		type redrawChecker interface {
			NeedsRedraw() bool
		}
		if rc, ok := w.(redrawChecker); ok && rc.NeedsRedraw() {
			return true
		}
	}

	// Always recurse into children (including through boundaries)
	// to find dirty non-boundary descendants.
	for _, child := range w.Children() {
		if NeedsRedrawInTreeNonBoundary(child) {
			return true
		}
	}

	return false
}

func StampScreenOrigin(child Widget, canvas Canvas) {
	type boundsGetter interface {
		Bounds() geometry.Rect
	}
	type originSetter interface {
		SetScreenOrigin(geometry.Point)
	}

	bg, hasBounds := child.(boundsGetter)
	setter, hasOrigin := child.(originSetter)
	if !hasBounds || !hasOrigin {
		return
	}

	childBounds := bg.Bounds()
	offset := canvas.TransformOffset().Add(canvas.ScreenOriginBase())
	screenOrigin := offset.Add(childBounds.Min)
	if debugStamp {
		fmt.Fprintf(os.Stderr, "[STAMP] %T bounds=%v canvasOffset=%v → screen=%v\n",
			child, childBounds, offset, screenOrigin)
	}
	setter.SetScreenOrigin(screenOrigin)
}

type ThemeProvider interface {
	// IsDark returns true if this is a dark theme.
	IsDark() bool

	// OnSurface returns the default color for text and icons on surface
	// backgrounds. Every design system (Material 3, Fluent, Cupertino)
	// defines an equivalent concept, making this a universal token.
	OnSurface() Color
}

type Widget interface {
	// Layout calculates the widget's size given constraints from the parent.
	//
	// The constraints define the minimum and maximum allowed dimensions.
	// The returned size must satisfy the constraints (within min/max bounds).
	//
	// Layout is called during the layout phase, before Draw. The widget
	// should calculate its preferred size and return it constrained to
	// the allowed range.
	//
	// For container widgets, Layout should:
	//  1. Layout all children with appropriate constraints
	//  2. Position children by setting their bounds
	//  3. Return the container's total size
	//
	// Example:
	//
	//	func (w *MyWidget) Layout(ctx Context, c geometry.Constraints) geometry.Size {
	//	    preferred := geometry.Sz(100, 50)
	//	    return c.Constrain(preferred)
	//	}
	Layout(ctx Context, constraints geometry.Constraints) geometry.Size

	// Draw renders the widget to the canvas.
	//
	// Draw is called after Layout, when the widget's bounds are established.
	// The canvas provides drawing operations for rendering the widget.
	//
	// For container widgets, Draw should:
	//  1. Draw the container's own content (background, border, etc.)
	//  2. Draw all visible children
	//
	// Example:
	//
	//	func (w *MyWidget) Draw(ctx Context, canvas Canvas) {
	//	    canvas.DrawRect(w.Bounds(), w.backgroundColor)
	//	    for _, child := range w.Children() {
	//	        child.Draw(ctx, canvas)
	//	    }
	//	}
	Draw(ctx Context, canvas Canvas)

	// Event handles an input event and returns true if consumed.
	//
	// Events are dispatched from the root widget down through the tree.
	// A widget that handles an event should return true to prevent
	// further propagation.
	//
	// For container widgets, Event should:
	//  1. Check if event is within bounds
	//  2. Dispatch to appropriate child widgets
	//  3. Handle the event if no child consumed it
	//
	// Example:
	//
	//	func (w *MyWidget) Event(ctx Context, e event.Event) bool {
	//	    if me, ok := e.(*event.MouseEvent); ok {
	//	        if !w.Bounds().Contains(me.Position) {
	//	            return false
	//	        }
	//	        if me.MouseType == event.MousePress {
	//	            w.onClick()
	//	            return true
	//	        }
	//	    }
	//	    return false
	//	}
	Event(ctx Context, e event.Event) bool

	// Children returns the widget's child widgets.
	//
	// Leaf widgets (like labels, buttons) return nil.
	// Container widgets return their children in z-order (bottom to top).
	//
	// The returned slice should not be modified by the caller.
	Children() []Widget
}

type RepaintBoundaryMarker interface {
	// MarkBoundaryDirty marks this repaint boundary as needing re-rendering.
	// Called by the upward dirty propagation in [WidgetBase.SetNeedsRedraw].
	MarkBoundaryDirty()
}
